package main
import("encoding/json";"encoding/binary";"flag";"fmt";"math";"os";"path/filepath";"strconv";"strings";"testing";"runtime";"os/exec";"bytes";"sort")
var history_qualification_out=flag.String("qualification-out","","fresh independent qualification report")
var history_qualification_cases=[]map[string]interface{}{}
var history_test_report_root string
func TestMain(m *testing.M){
 flag.Parse()
 history_test_report_root=os.Getenv("JT143_MIXING_HISTORY_REPORT_DIR")
 if history_test_report_root!=""{if e:=os.Mkdir(history_test_report_root,0755);e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
 code:=m.Run()
 output:=*history_qualification_out
 if output==""&&history_test_report_root!=""{output=filepath.Join(history_test_report_root,"synthetic.json")}
 if output!=""{data,e:=json.MarshalIndent(map[string]interface{}{"state":"independent_synthetic_qualification_only","test_exit_code":code,"cases":history_qualification_cases,"method_sha256":history_method_sha,"scope":"finite independent synthetic/parser checks; no model/physical data or real q band"},"","  ");if e==nil{e=history_write_exclusive(output,append(data,'\n'))};if e!=nil{fmt.Fprintln(os.Stderr,e);code=1}}
 os.Exit(code)
}
func history_test_dir(t *testing.T)string{t.Helper();if history_test_report_root!=""{return history_test_report_root};return t.TempDir()}
func history_host_dir(t *testing.T)string{t.Helper();_,current,_,ok:=runtime.Caller(0);if !ok{t.Fatal("test source location unavailable")};return filepath.Dir(current)}
func history_array_hash(v []float64)string{data:=make([]byte,2*len(v));for i,x:=range v{binary.LittleEndian.PutUint16(data[2*i:],uint16(int16(x)))};return history_hash(data)}
// Independent signals integrate native phase iteratively; never use the fitted basis.
func history_signal(inc,phase,amp,dc,gain,phase_step,return_gain,return_phase,return_dc float64)([]float64,[]float64){left,right:=make([]float64,16384),make([]float64,16384);angle:=phase;step:=2*math.Pi*inc/(1<<20);for n:=range right{g,p,d:=1.,0.,dc;if n>=4608&&n<9984{g,p=gain,phase_step};if n>=10496{g,p,d=return_gain,return_phase,dc+return_dc};v:=math.Round(g*amp*math.Sin(angle+p)+d);right[n]=math.Max(-32768,math.Min(32767,v));left[n]=right[n];if (n>=4096&&n<4608)||(n>=9984&&n<10496){left[n]=0};angle+=step};return left,right}
func history_memory_job(profile string,left,right []float64)*history_job{return &history_job{profile:profile,left:left,right:right,timing:history_timing{Source:"independent-native-integration",Start:10624},binding:map[string]interface{}{"test_only":true}}}
func history_number(t *testing.T,v interface{})float64{t.Helper();f,ok:=v.(float64);if !ok{t.Fatalf("not float: %T",v)};return f}
func TestNativeSignals(t *testing.T){count:=0;for _,phase:=range []float64{0,.37,2.8,5.9}{for _,amp:=range []float64{60,3000,14000}{for _,gain:=range []float64{.5,1,1.6}{left,right:=history_signal(4124,phase,amp,-8,gain,0,1,0,0);job:=history_memory_job("held-n01-tl32-40-32",left,right);r,err:=job.analyze();if err!=nil{t.Fatal(err)};if r["state"]!="geometry_observed_analysis_descriptive"{t.Fatal(r["state"])};low:=r["initial_low_fit"].(*history_fit);if math.Abs(low.Amplitude-amp)>.15{t.Fatalf("amplitude %g vs%g",low.Amplitude,amp)};beta_expected:=[3]float64{amp*math.Sin(phase),amp*math.Cos(phase),-8};for i,v:=range low.Beta{if math.Abs(v-beta_expected[i])>.15{t.Fatalf("independent coefficient %d=%g want%g",i,v,beta_expected[i])}};held:=r["initial_low_holdout"].(map[string]interface{});ret:=r["return_against_initial_prediction"].(map[string]interface{});if held["max_abs_pcm"].(float64)>.7||ret["max_abs_pcm"].(float64)>.7{t.Fatal("synthetic rounding residual")};transfer:=r["middle_transfer_from_initial"].(map[string]interface{});g:=transfer["amplitude_gain"].(*float64);if math.Abs(*g-gain)>.006{t.Fatalf("gain%g vs%g",*g,gain)};frequency:=r["frequency_diagnostics"].(map[string]interface{});if _,ok:=frequency["whole_right_held_low_noop_only"];ok{t.Fatal("whole piecewise frequency fit forbidden")};history_qualification_cases=append(history_qualification_cases,map[string]interface{}{"kind":"native_integrated_gain_phase_dc","increment":4124,"input_phase":phase,"amplitude":amp,"dc":-8,"middle_gain":gain,"right_pcm_le_i16_sha256":history_array_hash(right),"left_pcm_le_i16_sha256":history_array_hash(left),"report":r});count++}}};t.Logf("%d independently integrated native gain/phase/DC cases",count)}
func TestNoopWholeFrequencyAndWrongCarrier(t *testing.T){for _,inc:=range []float64{3900,4124}{for _,profile:=range []string{"held-n01-tl32-32-32","held-n32-tl32-32-32"}{left,right:=history_signal(inc,.6,12000,-8,1,0,1,0,0);r,err:=history_memory_job(profile,left,right).analyze();if err!=nil{t.Fatal(err)};frequency:=r["frequency_diagnostics"].(map[string]interface{});initial:=frequency["initial_low"].(map[string]interface{})["free_frequency"].(map[string]interface{});if initial["state"]!="free_frequency_sine_fit_observed_not_automatic_pass"{t.Fatal("3840-sample supported initial diagnostic",initial)};short,short_err:=fit_free_sine(right,128,1664);if short_err!=nil||short["state"]!="unresolved_insufficient_crossings"||short["measured_increment_20bit"]!=nil{t.Fatal("explicit1536-sample diagnostic must preserve fewer-than8 unresolved",short,short_err)};whole:=frequency["whole_right_held_low_noop_only"].(map[string]interface{});fit:=whole["free_frequency"].(map[string]interface{});measured:=history_number(t,fit["measured_increment_20bit"]);if math.Abs(measured-inc)>.002{t.Fatalf("free measurement%g vs%g",measured,inc)};raw:=whole["raw_zero_crossings"].(map[string]interface{});period:=raw["median_interval_recorded_samples"].(*float64);if math.Abs(*period-(1<<20)/inc)>.02{t.Fatalf("raw period%g",*period)};if inc==3900&&math.Abs(measured-4124)<200{t.Fatal("wrong rate silently returned expected")};history_qualification_cases=append(history_qualification_cases,map[string]interface{}{"kind":"noop_free_frequency_wrong_rate_control","increment":inc,"profile":profile,"right_pcm_le_i16_sha256":history_array_hash(right),"short_diagnostic":short,"report":r})}}}
func TestReturnDriftAndOverloadNoFit(t *testing.T){for _,change:=range []struct{gain,phase,dc float64}{{1,.04,0},{1.05,0,0},{1,0,18}}{left,right:=history_signal(4124,.7,12000,-8,2,0,change.gain,change.phase,change.dc);r,err:=history_memory_job("held-n32-tl32-00-32",left,right).analyze();if err!=nil{t.Fatal(err)};if _,ok:=r["middle_diagnostic_fit"];ok{t.Fatal("aggregate TL0 fitted")};freq:=r["frequency_diagnostics"].(map[string]interface{});if _,ok:=freq["middle"];ok{t.Fatal("overload frequency fit")};if _,ok:=freq["whole_right_held_low_noop_only"];ok{t.Fatal("whole overload fit")};res:=r["return_against_initial_prediction"].(map[string]interface{});if res["rms_pcm"].(float64)<10{t.Fatal("return change hidden")}};left,right:=history_signal(3900,.7,12000,-8,1,0,1,0,0);r,err:=history_memory_job("held-n32-tl32-32-32",left,right).analyze();if err!=nil{t.Fatal(err)};if r["initial_low_holdout"].(map[string]interface{})["rms_pcm"].(float64)<100{t.Fatal("wrong carrier fixed holdout hidden")}}
func TestNullWeakAndGeometry(t *testing.T){for _,amp:=range []float64{0,1,10}{left,right:=history_signal(4124,.2,amp,-8,1,0,1,0,0);if amp==0{for n:=range left{left[n]=1};for n:=4096;n<4608;n++{left[n]=0};for n:=9984;n<10496;n++{left[n]=0}};r,err:=history_memory_job("held-n01-tl32-32-32",left,right).analyze();if err!=nil{t.Fatal(err)};low:=r["initial_low_fit"].(*history_fit);if amp==0{if low.Phase!=nil||low.Amplitude!=0{t.Fatal("constant ghost phase")};transfer:=r["middle_transfer_from_initial"].(map[string]interface{});g:=transfer["amplitude_gain"].(*float64);if g!=nil{t.Fatal("constant gain invented")}};whole:=r["frequency_diagnostics"].(map[string]interface{})["whole_right_held_low_noop_only"].(map[string]interface{})["free_frequency"].(map[string]interface{});if whole["measured_increment_20bit"]!=nil{t.Fatal("weak frequency forced")}};left,right:=history_signal(4124,.2,1000,-8,1,0,1,0,0);job:=history_memory_job("held-n01-tl32-32-32",left,right);job.timing.Start=16000;r,_:=job.analyze();if r["state"]!="geometry_unresolved"{t.Fatal("late horizon fabricated")};for n:=4096;n<4608;n++{left[n]=1};for n:=4096;n<4351;n++{left[n]=0};r,_=job.analyze();if r["geometry_reason"]!="requires_exactly_two_observed_zero_runs_at_least256"{t.Fatal("255 marker accepted")}}
func history_fixture(t *testing.T,profile string)*history_job{t.Helper();dir:=t.TempDir();left,right:=history_signal(4124,.37,3000,-8,1,0,1,0,0);var csv strings.Builder;csv.WriteString("sample,left,right\n");for n:=range right{fmt.Fprintf(&csv,"%d,%.0f,%.0f\n",n,left[n],right[n])};input:=filepath.Join(dir,"input.csv");os.WriteFile(input,[]byte(csv.String()),0644);evidence:=filepath.Join(dir,"evidence.json");os.WriteFile(evidence,[]byte("{\"independent_integrated_signal\":true}\n"),0644);timing:=history_timing{Kind:"independent_synthetic",Source:"synthetic-shared-history",Input:history_hash([]byte(csv.String())),Marker:history_hash([]byte(csv.String())),Frames:16384,Stride:1,Upper:10496,Guard:128,Start:10624,Evidence:evidence,EvidenceHash:history_hash_file_must(evidence)};data,_:=json.Marshal(timing);timing_path:=filepath.Join(dir,"timing.json");os.WriteFile(timing_path,data,0644);method:=filepath.Join(history_host_dir(t),"testdata","mixing-history-method.json");return &history_job{profile:profile,input:input,column:"right",marker_column:"left",timing_path:timing_path,method_path:method,out:filepath.Join(dir,"out.json")}}
func TestFullAdapterAndReferences(t *testing.T){base:=history_fixture(t,"held-n32-tl32-32-32");base.curve=filepath.Join(filepath.Dir(base.out),"curve.csv");if err:=base.run();err!=nil{t.Fatal(err)};if err:=base.run();err==nil{t.Fatal("overwriting output")};n1:=history_fixture(t,"held-n01-tl32-40-32");if err:=n1.run();err!=nil{t.Fatal(err)};target:=history_fixture(t,"held-n32-tl32-40-32");target.noop=base.out;target.calibration=n1.out;if err:=target.run();err!=nil{t.Fatal(err)};data,_:=os.ReadFile(target.out);var report map[string]interface{};json.Unmarshal(data,&report);refs:=report["references"].(map[string]interface{});if refs["noop"]==nil||refs["n1_calibration"]==nil{t.Fatal("missing descriptive references")};bad:=history_fixture(t,"held-n32-tl32-00-32");bad.calibration=n1.out;if err:=bad.run();err==nil{t.Fatal("wrong TL reference accepted")};bad=history_fixture(t,"held-n32-tl32-40-32");bad.noop=n1.out;if err:=bad.run();err==nil{t.Fatal("wrong N1 noop accepted")};bad=history_fixture(t,"held-n32-tl32-40-32");bad.noop=base.out;td,_:=os.ReadFile(bad.timing_path);td=[]byte(strings.Replace(string(td),"synthetic-shared-history","other-source",1));os.WriteFile(bad.timing_path,td,0644);if err:=bad.run();err==nil{t.Fatal("source mismatch accepted")}}
func TestMalformedCSV(t *testing.T){base:=history_fixture(t,"held-n01-tl32-32-32");data,_:=os.ReadFile(base.input);original:=string(data);cases:=map[string]string{"header":strings.Replace(original,"sample,left,right","sample,right,left",1),"nonconsecutive":strings.Replace(original,"\n1,","\n2,",1),"nonfinite":strings.Replace(original,strings.Split(original,"\n")[1],"0,NaN,0",1),"fractional":strings.Replace(original,strings.Split(original,"\n")[1],"0,0.5,0",1),"nonselected_range":strings.Replace(original,strings.Split(original,"\n")[1],"0,32768,0",1),"missing":strings.Join(strings.Split(original,"\n")[:16384],"\n"),"extra":original+"16384,0,0\n","fields":strings.Replace(original,"\n1,","\n1,9,",1)};for name,s:=range cases{t.Run(name,func(t *testing.T){path:=filepath.Join(t.TempDir(),"bad.csv");os.WriteFile(path,[]byte(s),0644);if _,err:=history_trace_read(path);err==nil{t.Fatal("malformed accepted")}})}}
func TestTimingAndCLIContracts(t *testing.T){for _,name:=range []string{"hash","evidence","source","stride","guard","start","negative","missing","unknown","duplicate","trailing","kind"}{t.Run(name,func(t *testing.T){job:=history_fixture(t,"held-n01-tl32-32-32");data,_:=os.ReadFile(job.timing_path);var m map[string]interface{};json.Unmarshal(data,&m);switch name{case "hash":m["input_sha256"]="bad";case "evidence":m["evidence_sha256"]="bad";case "source":m["source_id"]="";case "stride":m["native_stride"]=2;case "guard":m["guard_native"]=127;case "start":m["final_post_start_native"]=10625;case "negative":m["final_event_upper_native"]=-1;case "missing":delete(m,"final_event_upper_native");case "unknown":m["q"]=1;case "kind":m["kind"]="public_model_sidecar"};data,_=json.Marshal(m);if name=="duplicate"{data=append([]byte("{\"guard_native\":128,"),data[1:]...)};if name=="trailing"{data=append(data,[]byte("{}")...)};os.WriteFile(job.timing_path,data,0644);if err:=job.load();err==nil{t.Fatal("bad timing accepted")}})};job:=history_fixture(t,"bad-profile");if err:=job.load();err==nil{t.Fatal("bad profile")};job=history_fixture(t,"held-n01-tl32-32-32");job.column="left";if err:=job.load();err==nil{t.Fatal("wrong role")};if err:=history_fresh_paths([]string{job.out,job.out});err==nil{t.Fatal("same outputs")};job=history_fixture(t,"held-n01-tl32-32-32");job.method_path=job.timing_path;if err:=job.load();err==nil{t.Fatal("bad method")}}
func TestPhysicalAndModelSchemas(t *testing.T){dir:=t.TempDir();for _,kind:=range []string{"physical","jt51","opm"}{var builder strings.Builder;switch kind{case "physical":builder.WriteString("sample,raw16_hex,linear\n");case "jt51":builder.WriteString("sample,left,right,xleft,xright,clock,status\n");case "opm":builder.WriteString("sample,left,right,clock,inc0,inc8,inc16,inc24,phase24\n")};for n:=0;n<16384;n++{switch kind{case "physical":fmt.Fprintf(&builder,"%d,3000,0\n",n);case "jt51":fmt.Fprintf(&builder,"%d,1,-1,2,-2,%d,0\n",n,n*64+32);case "opm":fmt.Fprintf(&builder,"%d,1,-1,%d,4124,4124,4124,4124,0\n",n,n*64+64)}};original:=builder.String();path:=filepath.Join(dir,kind+".csv");os.WriteFile(path,[]byte(original),0644);trace,err:=history_trace_read(path);if err!=nil||trace.kind!=kind{t.Fatalf("valid %s: %v",kind,err)};mutations:=[]string{};if kind=="physical"{mutations=[]string{strings.Replace(original,"3000,0","1000,0",1),strings.Replace(original,"3000,0","3008,0",1),strings.Replace(original,"3000,0","g000,0",1),strings.Replace(original,"3000,0","03000,0",1)}}else{clock:=int64(96);if kind=="opm"{clock=128};mutations=[]string{strings.Replace(original,","+strconv.FormatInt(clock,10)+",",","+strconv.FormatInt(clock+1,10)+",",1),strings.Replace(original,"\n0,1,","\n0,NaN,",1)}};for _,bad:=range mutations{os.WriteFile(path,[]byte(bad),0644);if _,err:=history_trace_read(path);err==nil{t.Fatalf("bad %s accepted",kind)}}}}
func TestGeometryBoundaryAndNoise(t *testing.T){for _,first:=range []int{1791,1792}{left,right:=history_signal(4124,.4,3000,-8,1,0,1,0,0);for n:=range left{left[n]=1};for _,w:=range []history_interval{{first,first+256},{6144,6400}}{for n:=w.First;n<w.End;n++{left[n]=0}};r,err:=history_memory_job("held-n01-tl32-32-32",left,right).analyze();if err!=nil{t.Fatal(err)};if first==1791&&r["state"]!="geometry_unresolved"{t.Fatal("1535 accepted")};if first==1792&&r["state"]!="geometry_observed_analysis_descriptive"{t.Fatal("1536 rejected")}};left,right:=history_signal(4124,.4,3000,-8,1,0,1,0,0);state:=uint32(0x12345678);for n:=range right{state^=state<<13;state^=state>>17;state^=state<<5;right[n]=float64(int(state%2001)-1000)};r,err:=history_memory_job("held-n01-tl32-32-32",left,right).analyze();if err!=nil{t.Fatal(err)};whole:=r["frequency_diagnostics"].(map[string]interface{})["whole_right_held_low_noop_only"].(map[string]interface{})["free_frequency"].(map[string]interface{});if strings.Contains(whole["state"].(string),"automatic_pass")&&!strings.Contains(whole["state"].(string),"not_automatic_pass"){t.Fatal("automatic noise pass")};if value,ok:=whole["sine_rms_pcm"].(float64);ok&&value<400{t.Fatal("noise spuriously pure")};history_qualification_cases=append(history_qualification_cases,map[string]interface{}{"kind":"generic_prng_no_carrier","right_pcm_le_i16_sha256":history_array_hash(right),"report":r})}
func TestPhysicalPairEndToEnd(t *testing.T){job:=history_fixture(t,"held-n01-tl32-32-32");left,right:=history_signal(4124,.7,3000,-8,1,0,1,0,0);paths:=[]string{filepath.Join(filepath.Dir(job.out),"right.csv"),filepath.Join(filepath.Dir(job.out),"left.csv")};for k,values:=range [][]float64{right,left}{var b strings.Builder;b.WriteString("sample,raw16_hex,linear\n");for n,v:=range values{linear:=int(math.Round(v/8))*8;word:=(4<<13)|(((linear/8)+512)<<3);fmt.Fprintf(&b,"%d,%04x,%d\n",n,word,linear)};os.WriteFile(paths[k],[]byte(b.String()),0644)};job.input,job.marker=paths[0],paths[1];job.column,job.marker_column="linear","linear";data,_:=os.ReadFile(job.timing_path);var timing history_timing;json.Unmarshal(data,&timing);timing.Kind="physical_host_upper";timing.Input=history_hash_file_must(paths[0]);timing.Marker=history_hash_file_must(paths[1]);data,_=json.Marshal(timing);os.WriteFile(job.timing_path,data,0644);if err:=job.run();err!=nil{t.Fatal(err)};single:=*job;single.marker=single.input;if err:=single.load();err==nil{t.Fatal("same physical trace used for both roles")};late:=*job;late.out=filepath.Join(filepath.Dir(job.out),"late.json");timing.Upper=19000;timing.Start=19128;data,_=json.Marshal(timing);os.WriteFile(job.timing_path,data,0644);if err:=late.run();err!=nil{t.Fatal("genuine late horizon should be retained unresolved",err)};result_data,_:=os.ReadFile(late.out);var report map[string]interface{};json.Unmarshal(result_data,&report);if report["state"]!="geometry_unresolved"{t.Fatal("late timing fabricated support")}}

