func history_literal_ops(data []byte)([][3]int,error){
 ops:=[][3]int{}
 for pos:=0;pos<len(data);{op:=int(data[pos]);pos++;if op==0{if pos!=len(data){return nil,fmt.Errorf("trailing bytecode")};return ops,nil};if op!=1&&op!=2||pos+2>len(data){return nil,fmt.Errorf("malformed bytecode")};a,b:=int(data[pos]),int(data[pos+1]);pos+=2;if op==1{ops=append(ops,[3]int{1,a,b})}else{ops=append(ops,[3]int{2,a|b<<8,0})}}
 return nil,fmt.Errorf("missing bytecode END")
}
